# ---------------------------------------------------------------------------
# Helper Functions
# ---------------------------------------------------------------------------
def extract_imports(content: str) -> Set[str]:
    """Extract all import statements from JS content using regex."""
    imports = set()
    # ES6 imports
    es6_pattern = r"import\s+(?:[\w\s{},*]+\s+from\s+)?['\"]([^'\"]+)['\"]"
    imports.update(re.findall(es6_pattern, content))
    # CommonJS requires
    cjs_pattern = r"require\(['\"]([^'\"]+)['\"]\)"
    imports.update(re.findall(cjs_pattern, content))
    return imports


def extract_mock_calls(content: str) -> Set[str]:
    """Extract jest.mock() calls from JS content."""
    pattern = r"jest\.mock\(['\"]([^'\"]+)['\"]"
    return set(re.findall(pattern, content))


def extract_test_names(content: str) -> List[str]:
    """Extract test/it case names from JS content."""
    pattern = r"(?:test|it)\(['\"]([^'\"]+)['\"]"
    return re.findall(pattern, content)


def extract_describe_blocks(content: str) -> List[str]:
    """Extract describe block names from JS content."""
    pattern = r"describe\(['\"]([^'\"]+)['\"]"
    return re.findall(pattern, content)


def validate_js_syntax(content: str) -> Tuple[bool, str]:
    """Validate JS syntax using Node.js in a subprocess."""
    with tempfile.NamedTemporaryFile(mode="w", suffix=".js", delete=False) as f:
        f.write(content)
        temp_path = f.name
    try:
        result = subprocess.run(
            ["node", "--check", temp_path],
            capture_output=True,
            text=True,
            timeout=10,
        )
        if result.returncode == 0:
            return True, "Syntax valid"
        return False, result.stderr.strip()
    except subprocess.SubprocessError as e:
        return False, f"Subprocess error: {e}"
    finally:
        os.unlink(temp_path)


def calculate_line_coverage(harness: str, source: str) -> float:
    """Estimate line coverage of source by harness using string matching."""
    source_lines = source.splitlines()
    if not source_lines:
        return 0.0
    covered_lines = 0
    for line in source_lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("//") or stripped.startswith("/*"):
            continue
        # Check if any part of the line appears in the harness
        identifiers = re.findall(r"[a-zA-Z_$][\w$]*", stripped)
        if any(ident in harness for ident in identifiers):
            covered_lines += 1
    return (covered_lines / len(source_lines)) * 100


