class TestMutationResistance:
    """Detect if test names or structure have been tampered with."""

    def test_test_names_match_expected_pattern(self, harness_content):
        """Test that test names follow the expected naming convention."""
        test_names = extract_test_names(harness_content)
        for name in test_names:
            assert re.match(r"^[a-z][a-z0-9\s\-_]*$", name), (
                f"Test name '{name}' does not follow naming convention"
            )

    def test_no_duplicate_test_names(self, harness_content):
        """Test that there are no duplicate test names."""
        test_names = extract_test_names(harness_content)
        duplicates = [name for name in set(test_names) if test_names.count(name) > 1]
        assert not duplicates, f"Duplicate test names: {duplicates}"

    def test_required_test_cases_not_renamed(self, harness_content):
        """Test that required test cases have not been renamed."""
        test_names = extract_test_names(harness_content)
        for required in REQUIRED_TEST_CASES:
            # Check for exact match or close variant
            found = any(
                required in name or name in required
                for name in test_names
            )
            assert found, f"Required test case '{required}' not found or renamed"

    def test_mock_names_not_tampered(self, harness_content):
        """Test that mock names match expected patterns."""
        mocks = extract_mock_calls(harness_content)
        for mock in mocks:
            assert mock.startswith(("src/", "dompurify", "ResourceUtilizationChart")), (
                f"Unexpected mock target: {mock}"
            )


