        """Test that the harness has consistent indentation."""
        lines = harness_content.splitlines()
        indent_counts = set()
        for line in lines:
            if line.strip():
                indent = len(line) - len(line.lstrip())
                indent_counts.add(indent % 2)  # Check for even indentation
        assert len(indent_counts) <= 2, "Inconsistent indentation detected"


